CREATE OR REPLACE FUNCTION private.audit_content_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  resource text;
begin
  resource := case when tg_op = 'DELETE' then old.id::text else new.id::text end;
  insert into public.admin_audit_logs (
    actor_id, action, resource_type, resource_id, safe_metadata
  ) values (
    (select auth.uid()), lower(tg_op), tg_table_name, resource,
    jsonb_build_object(
      'status_before', case when tg_op in ('UPDATE','DELETE') then to_jsonb(old)->>'status' end,
      'status_after', case when tg_op in ('INSERT','UPDATE') then to_jsonb(new)->>'status' end
    )
  );
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.configure_ai_provider(p_slug text, p_display_name text, p_adapter text, p_base_url text, p_api_key text, p_enabled boolean DEFAULT false, p_priority integer DEFAULT 100)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_secret_id uuid;
begin
  if not private.has_role(array['super_admin']) then raise exception 'forbidden' using errcode='42501'; end if;
  if p_slug !~ '^[a-z0-9_]+$' or p_adapter not in ('openai_compatible','anthropic','gemini')
    or p_base_url not like 'https://%' or length(coalesce(p_api_key,'')) < 8 then
    raise exception 'invalid provider configuration' using errcode='22023';
  end if;
  select secret_id into v_secret_id from public.ai_providers where slug=p_slug;
  if v_secret_id is null then
    v_secret_id := vault.create_secret(p_api_key,'ai_provider_'||p_slug,'RAD AI provider credential');
  else
    perform vault.update_secret(v_secret_id,p_api_key,'ai_provider_'||p_slug,'RAD AI provider credential');
  end if;
  insert into public.ai_providers(slug,display_name,adapter,base_url,secret_id,enabled,priority)
  values(p_slug,p_display_name,p_adapter,rtrim(p_base_url,'/'),v_secret_id,p_enabled,p_priority)
  on conflict(slug) do update set display_name=excluded.display_name,adapter=excluded.adapter,
    base_url=excluded.base_url,secret_id=excluded.secret_id,enabled=excluded.enabled,
    priority=excluded.priority,updated_at=now() returning id into v_id;
  insert into public.ai_provider_health(provider_id) values(v_id) on conflict do nothing;
  insert into public.admin_audit_logs(actor_id,action,resource_type,resource_id,safe_metadata)
  values(auth.uid(),'configure','ai_provider',v_id::text,jsonb_build_object('slug',p_slug,'enabled',p_enabled,'adapter',p_adapter));
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION private.observability_retention()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 delete from public.component_health_checks where checked_at < now()-interval '90 days';
 delete from public.operational_events where occurred_at < now()-interval '30 days' and severity not in ('critical');
 delete from public.operational_events where occurred_at < now()-interval '365 days';
 update public.research_jobs set status='failed',finished_at=now(),safe_error='Worker lease expired',error_code='lease_expired'
  where status='running' and started_at<now()-interval '20 minutes';
 update public.document_processing_jobs set status='failed',finished_at=now(),safe_error_code='lease_expired'
  where status='running' and started_at<now()-interval '10 minutes';
end $function$

CREATE OR REPLACE FUNCTION private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_user_role(p_user_id uuid, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_role text;
begin
 if not private.has_role(array['super_admin']) then raise exception 'forbidden' using errcode='42501'; end if;
 if p_role not in ('user','admin','super_admin') then raise exception 'invalid role' using errcode='22023'; end if;
 select role into old_role from public.profiles where id=p_user_id for update;
 if old_role is null then raise exception 'profile not found' using errcode='P0002'; end if;
 update public.profiles set role=p_role,updated_at=now() where id=p_user_id;
 insert into public.admin_audit_logs(actor_id,action,resource_type,resource_id,safe_metadata)
 values(auth.uid(),'role_change','profile',p_user_id::text,jsonb_build_object('from',old_role,'to',p_role));
end $function$
